import{_ as o}from"./chunks/48.KlG-covB.js";import{_ as r}from"./chunks/10.CjdpXPJn.js";import{_ as n}from"./chunks/0.xVPDiwtD.js";import{_ as s}from"./chunks/25.Bnsp-MNl.js";import{_ as l}from"./chunks/0.B7TrDeTt.js";import{_ as d}from"./chunks/1.BU1qyW7B.js";import{_ as c}from"./chunks/0.DyB7G7H5.js";import{_ as g}from"./chunks/5.BkY6Rw8O.js";import{_ as t}from"./chunks/0.C_OEUMPL.js";import{_ as h}from"./chunks/9._7FszrLL.js";import{_ as p}from"./chunks/100.DMbJtyMU.js";import{_ as m}from"./chunks/community.BdKwbEUF.js";import{_ as u,C as f,o as y,c as _,ak as a,E as b}from"./chunks/framework.sbZkgmEx.js";const w="/projects/AiBlock/en/advanced-kit/assets/1.DvuhSptL.webp",v="/projects/AiBlock/en/advanced-kit/assets/2.1.l0cjGppv.webp",x="/projects/AiBlock/en/advanced-kit/assets/2.1.BAk-fKUi.webp",k="/projects/AiBlock/en/advanced-kit/assets/2.2.B-zWBZGO.webp",P="/projects/AiBlock/en/advanced-kit/assets/3.CIcqWFrD.webp",q="/projects/AiBlock/en/advanced-kit/assets/4.DVv8mCxp.webp",L=JSON.parse('{"title":"3.48 Zero-Gravity Drop Tower","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.48 Zero-Gravity Drop Tower.md","filePath":"docs/3.Creative Builds/3.48 Zero-Gravity Drop Tower.md"}'),T={name:"docs/3.Creative Builds/3.48 Zero-Gravity Drop Tower.md"};function A(B,e,C,j,D,z){const i=f("Pdf");return y(),_("div",null,[e[0]||(e[0]=a('<h1 id="_3-48-zero-gravity-drop-tower" tabindex="-1">3.48 Zero-Gravity Drop Tower <a class="header-anchor" href="#_3-48-zero-gravity-drop-tower" aria-label="Permalink to &quot;3.48 Zero-Gravity Drop Tower&quot;">​</a></h1><h2 id="_3-48-1-lesson-introduction" tabindex="-1">3.48.1 Lesson Introduction <a class="header-anchor" href="#_3-48-1-lesson-introduction" aria-label="Permalink to &quot;3.48.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on a smart drop tower model, this lesson explores coordinated programming among a motor, an infrared sensor, and lighting modules. It implements an automated amusement ride routine featuring vertical hoisting, peak-triggered descent, continuous cyclic operation, and synchronized lighting cues. The content illustrates fixed pulley transmission principles and bidirectional motor rotation control methods. It applies non-contact infrared triggering logic. Furthermore, it examines core design principles of human-robot interaction in automated amusement park attractions.</p><img loading="lazy" height="1690" width="1690" src="'+o+'" class="common_img" style="width:400px;"><h2 id="_3-48-2-learning-objectives" tabindex="-1">3.48.2 Learning Objectives <a class="header-anchor" href="#_3-48-2-learning-objectives" aria-label="Permalink to &quot;3.48.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand linear hoisting mechanics in fixed pulley guide-rail structures, redirecting applied force without altering mechanical advantage. Master non-contact triggering principles using the infrared obstacle avoidance sensor. Understand control logic mapping forward and reverse motor rotation to vertical ascent and descent. Explore interactive design concepts using RGB colors and dot matrix graphics as real-time status indicators.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the guide rail and fixed pulley mechanisms of the zero-gravity drop tower independently, mastering suspension cable rigging techniques. Construct basic motor control routines to manage bidirectional elevation. Implement a fully automated cyclic routine integrating infrared peak detection, automatic free-fall descent, red and green status lighting, and directional arrow graphics.</p></li><li><p><strong>Thinking Objectives</strong>: Build automation thinking centered on non-contact detection and automated triggering, and appreciate the value of sensor-based autonomous control. Cultivate feedback-oriented interaction design thinking, learning to communicate operational states through colors and iconography. Reinforce programming logic for closed-loop, continuous cyclic automation.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to practical applications including amusement drop towers, passenger elevators, automated sliding doors, and sensor-activated faucets. Understand widespread implementations of non-contact proximity sensing in smart appliances. Inspire exploration into amusement ride engineering, vertical transportation technology, and intelligent sensory systems.</p></li></ol><h2 id="_3-48-3-preparation" tabindex="-1">3.48.3 Preparation <a class="header-anchor" href="#_3-48-3-preparation" aria-label="Permalink to &quot;3.48.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>Infrared obstacle avoidance sensor</p></li><li><p>RGB light module</p></li><li><p>Dot matrix module</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab graphical programming platform</li></ul><h2 id="_3-48-4-hands-on-project" tabindex="-1">3.48.4 Hands-On Project <a class="header-anchor" href="#_3-48-4-hands-on-project" aria-label="Permalink to &quot;3.48.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Zero-Gravity Drop Tower, achieving a fully automated operational cycle featuring automated hoisting, peak-triggered free fall, and synchronized audiovisual feedback. The system employs an architecture combining fixed pulley linear hoisting, infrared non-contact triggering, and real-time sensory feedback. A motor drives the passenger gondola vertically along the guide rail via a suspension cable, rotating in reverse to ascend and forward to descend. An infrared obstacle avoidance sensor mounted at the top detects gondola arrival without physical contact, triggering an automated directional reversal. During ascent, an RGB red breathing light pairs with an upward arrow display. During descent, a green light pairs with a downward arrow, providing dual visual confirmation of operating status. Triggering Button A initiates continuous cyclic execution across ascending, peak sensing, dropping, and re-ascending, authentically reproducing the thrill of a commercial amusement drop tower.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),b(i,{src:"../../_static/shared/pdf/chapter_3/48.pdf"}),e[1]||(e[1]=a('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the Infrared obstacle avoidance sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li><li><p>Connect the RGB light module to port <strong>B</strong> of the controller using a 4-pin module cable.</p></li><li><p>Connect the dot matrix module to port <strong>C</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1655" width="2520" src="'+w+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Avoid obstacle sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+v+'" class="common_img" style="width:800px;"><ul><li>Select <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+x+'" class="common_img" style="width:800px;"><ul><li>Select <strong>Dot matrix module</strong> and <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+k+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="174" width="603" src="'+r+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+n+'"></td><td style="text-align:left;">Serve as an event listener block that executes nested program statements when a designated button action is detected.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="87" width="905" src="'+s+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+l+'"></td><td style="text-align:left;">Read the detection status of the Infrared obstacle avoidance sensor at the designated port, returning a Boolean value to determine whether an obstacle is detected ahead.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+c+'"></td><td style="text-align:left;">Drive the 360° block motor at a designated port to rotate continuously at a customized speed in the forward or reverse direction.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="280" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Control the dot matrix module at the designated port to load and display preset graphic patterns.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="811" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Control the RGB light module at the designated port to activate a breathing color cycle, with customizable transition periods.</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="550" width="510" src="'+P+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>When Button A on the left is pressed, the main routine begins execution. If the Infrared obstacle avoidance sensor detects the gondola at the top, the dot matrix module displays a downward arrow, motor S1 rotates forward at 80% speed to drop the gondola, and the RGB light module pulses with a green breathing effect for 2 s. Otherwise, the dot matrix module displays an upward arrow, motor S1 rotates in reverse at 80% speed to hoist the gondola upward, and the RGB light module emits a red breathing effect with a 1 s period.</p></li></ul><img loading="lazy" height="558" width="950" src="'+q+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+p+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1adJTOnyve2MmEehrB9YFSW8echTWwoF2?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-48-5-expansion-and-challenge" tabindex="-1">3.48.5 Expansion and Challenge <a class="header-anchor" href="#_3-48-5-expansion-and-challenge" aria-label="Permalink to &quot;3.48.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Cushion-Braking Drop Tower</strong></p><p>Install a secondary infrared sensor near the base of the tower. When the sensor detects the descending gondola approaching the bottom, the motor automatically throttles down from 80% to 20% speed for a gentle landing, simulating progressive cushion braking. Practice multi-sensor segmented control and gradual velocity transitions while understanding deceleration safety mechanisms. Extend discussions to elevator floor leveling, roller coaster magnetic brakes, and industrial crane hoist safety systems.</p><p><strong>Project 2: Multi-Stage Variable Velocity Drop Tower</strong></p><p>Ascend at a steady 50% velocity, drop rapidly at 80% speed from the summit to simulate free-fall weightlessness, and decelerate midway down to cushion the landing. Practice multi-stage velocity sequencing and experiential pacing design. Extend discussions to velocity profiling in roller coaster drops and the physiological sensation of weightlessness.</p><h2 id="_3-48-6-q-a" tabindex="-1">3.48.6 Q&amp;A <a class="header-anchor" href="#_3-48-6-q-a" aria-label="Permalink to &quot;3.48.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: What is non-contact triggering, and how does the infrared sensor detect an approaching object without physical contact?</strong></p><p>Answer: Non-contact triggering refers to <strong>detecting the presence of an object across a distance without physical touch</strong>. The infrared sensor emits an invisible beam of infrared light. When this light strikes an approaching object, it reflects back toward the sensor receiver. Detecting this reflected signal informs the system that an object has arrived in front of the probe. Because the interaction occurs entirely across the air gap without mechanical collision, it is designated as non-contact detection. This approach provides significant engineering advantages: it eliminates mechanical wear, prevents structural impact damage, delivers rapid response times, and ensures clean operation. Everyday applications are widespread: automatic doors open when pedestrians approach, sensor faucets release water when hands are placed beneath them, elevator door curtains prevent closure when beams are interrupted, and automatic soap dispensers dispense foam upon proximity detection. Using an infrared sensor to detect the gondola at the peak avoids collisions with mechanical limit switches, delivering quiet, precise, and wear-free triggering.</p><p><strong>Question 2: Why does the ride use red lighting for ascent and green lighting for descent, and what principles govern color selection?</strong></p><p>Answer: The color scheme represents <strong>intuitive human-robot interaction design aligned with universal cognitive habits</strong>. In visual signaling, red universally communicates warning, caution, and anticipation. During ascent, the ride climbs steadily against gravity, storing potential energy. Red illumination cautions observers that hoisting is underway, while building dramatic tension. Conversely, green universally signals clear passage, release, and normal operation. The free fall represents this energy release, where green confirms active, unrestricted descent. Adopting this standard color coding aligns with everyday intuition, much like traffic stoplights that everyone comprehends instantly. Inverting the colors would create cognitive dissonance because it contradicts established cultural conventions. Effective status design requires intuitive readability without training. Combining color coding with directional arrow graphics on the dot matrix display establishes dual visual confirmation, ensuring that system states communicate clearly and reliably.</p><h2 id="_3-48-7-technical-support-and-product-discussion" tabindex="-1">3.48.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-48-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.48.7 Technical Support and Product Discussion&quot;">​</a></h2><p>Submit questions or share project modifications in the community forum:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+m+'" class="common_img" style="width:800px;"></a>',33))])}const M=u(T,[["render",A]]);export{L as __pageData,M as default};
